Load cached values from the active sheet and group rows by the stripped column C name.  
For each name, find the maximum column I datetime and compare each row's Entry Time to it.  
Write 'Latest' or 'Not Latest' into M2:M41 and save the workbook to OUT.

```python
import shutil
import openpyxl
from datetime import datetime, timedelta, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
sheet_name = vws.title
ws = wb[sheet_name]

def to_dt(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        return datetime(1899, 12, 30) + timedelta(days=float(v))
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.fromisoformat(s)
        except ValueError:
            pass
        for fmt in (
            "%Y-%m-%d %H:%M:%S.%f",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%d.%m.%Y %H:%M:%S",
            "%d.%m.%Y",
        ):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return None

last_row = min(max(2, vws.max_row), 41)

rows = []
max_by_name = {}

for r in range(2, last_row + 1):
    c = vws.cell(row=r, column=3).value
    i = vws.cell(row=r, column=9).value
    dt = to_dt(i)
    key = str(c).strip() if c is not None else None

    rows.append((r, key, dt))

    if key is not None and dt is not None:
        if key not in max_by_name or dt > max_by_name[key]:
            max_by_name[key] = dt

for r, key, dt in rows:
    if key is None or dt is None:
        ws.cell(row=r, column=13).value = None
    else:
        ws.cell(row=r, column=13).value = "Latest" if dt == max_by_name[key] else "Not Latest"

wb.save(OUT)

print("sheet:", sheet_name, "last_row:", last_row)
print("max_by_name:", {k: str(v) for k, v in max_by_name.items()})
for r in range(2, min(last_row, 6) + 1):
    print(r, ws.cell(row=r, column=13).value)
